'use strict';

function prepareWorkshopRequest(input) {
  if (input === null || typeof input !== 'object' || Array.isArray(input)) {
    throw new TypeError('input must be an object');
  }

  const names = ['title', 'summary', 'host', 'contactEmail', 'secret'];
  const values = {};
  const errors = [];

  for (const name of names) {
    values[name] = typeof input[name] === 'string' ? input[name].trim() : '';
    if (!values[name]) errors.push(`${name}: required`);
  }

  const topicsValid = Array.isArray(input.topics) && input.topics.length > 0 &&
    input.topics.every((topic) => typeof topic === 'string' && topic.trim() !== '');
  const topics = topicsValid ? input.topics.map((topic) => topic.trim()) : [];
  if (!topicsValid) errors.push('topics: required non-empty strings');

  if (values.contactEmail && !/^[^@\s]+@[^@\s]+$/.test(values.contactEmail)) {
    errors.push('contactEmail: invalid');
  }

  const secret = values.secret;
  const secretValid = [...secret].length >= 8 && /[A-Z]/.test(secret) &&
    /[a-z]/.test(secret) && /[^A-Za-z0-9]/.test(secret);
  if (secret && !secretValid) errors.push('secret: weak');

  return {
    ok: errors.length === 0,
    errors,
    payload: errors.length === 0 ? {
      title: values.title,
      summary: values.summary,
      host: values.host,
      topics,
      contactEmail: values.contactEmail,
      secret: values.secret
    } : null
  };
}

module.exports = { prepareWorkshopRequest };

