'use strict';

const assert = require('node:assert');
const api = require('./solution');

assert.deepStrictEqual(Reflect.ownKeys(api), ['prepareWorkshopRequest']);
const { prepareWorkshopRequest } = api;
assert.strictEqual(typeof prepareWorkshopRequest, 'function');

const topics = Object.freeze([' JavaScript ', '\tTesting\n']);
const input = Object.freeze({
  title: '  Behavioral Testing ',
  summary: ' Build robust tests. ',
  host: '\tAda\n',
  contactEmail: ' ada@example.com ',
  secret: ' Aa1!😀😀😀😀 ',
  topics
});
const success = prepareWorkshopRequest(input);
assert.deepStrictEqual(success, {
  ok: true,
  errors: [],
  payload: {
    title: 'Behavioral Testing',
    summary: 'Build robust tests.',
    host: 'Ada',
    contactEmail: 'ada@example.com',
    secret: 'Aa1!😀😀😀😀',
    topics: ['JavaScript', 'Testing']
  }
});
assert.notStrictEqual(success.payload, input);
assert.notStrictEqual(success.payload.topics, topics);
success.payload.topics.push('New');
assert.deepStrictEqual(topics, [' JavaScript ', '\tTesting\n']);

const base = {
  title: 'Title', summary: 'Summary', host: 'Host',
  contactEmail: 'a@b', secret: 'Abcdef1!', topics: ['topic']
};
function errorsFor(change) {
  const result = prepareWorkshopRequest({ ...base, ...change });
  assert.strictEqual(result.ok, false);
  assert.strictEqual(result.payload, null);
  assert.ok(Array.isArray(result.errors));
  return result.errors;
}

const titleError = errorsFor({ title: ' ' });
const hostError = errorsFor({ host: '\t' });
const topicsError = errorsFor({ topics: ['valid', ' '] });
const emailError = errorsFor({ contactEmail: 'a@@b' });
const secretError = errorsFor({ secret: 'abcdefgh' });
for (const isolated of [titleError, hostError, topicsError, emailError, secretError]) {
  assert.strictEqual(isolated.length, 1);
}
const combined = errorsFor({
  title: ' ', host: ' ', topics: [], contactEmail: 'a b@c', secret: 'short'
});
assert.deepStrictEqual(combined, [
  ...titleError,
  ...hostError,
  ...topicsError,
  ...emailError,
  ...secretError
]);

for (const field of ['title', 'summary', 'host', 'contactEmail', 'secret']) {
  assert.strictEqual(errorsFor({ [field]: ' ' }).length, 1);
}
for (const email of ['@b', 'a@', 'a@b@c', 'a b@c']) {
  assert.strictEqual(errorsFor({ contactEmail: email }).length, 1);
}
for (const secret of ['Abcdef1', 'abcdef1!', 'ABCDEF1!', 'Abcdefg!', 'Abcdef12']) {
  assert.strictEqual(errorsFor({ secret }).length, 1);
}

for (const badInput of [null, undefined, [], 'x', 1, true]) {
  assert.throws(() => prepareWorkshopRequest(badInput), TypeError);
}

